const CATS = { lead: ['Lead', 'st-ok'], support: ['Support', 'st-wait'], billing: ['Billing', 'st-info'], meeting: ['Meeting', 'st-info'], newsletter: ['Newsletter', 'st-info'], suspicious: ['Suspicious', 'st-bad'], other: ['Other', 'st-info'] };
