.sample form{display:inline}.sample button,.btn2{border:0;cursor:pointer;font:inherit;font-weight:600;font-size:14px;background:#0f2a4a;color:#fff;padding:8px 12px;border-radius:9px}.sample a{font-size:14px;margin-left:8px}
input[type=file]{display:block;width:100%;padding:14px;border:2px dashed #c9d3e3;border-radius:12px;background:#fafbfd;font:inherit;margin:8px 0 14px}
button.btn{border:0;cursor:pointer;font:inherit;font-weight:600;font-size:16px}pre.draft{white-space:pre-wrap;font:inherit;font-size:15px;background:#fafbfd;border:1px solid #e3e8ef;border-radius:10px;padding:14px 16px;margin:0}
.mail{border:1px solid #e3e8ef;border-radius:12px;padding:14px 16px;background:#fff}.mail .hd{font-size:13px;color:#5b6576;margin-bottom:8px}.mail .hd b{color:#1d2433}
form label{display:block;font-weight:600;font-size:14px;color:#344054;margin:14px 0 6px}form input:not([type=hidden]),form textarea{display:block;width:100%;padding:11px 12px;border:1px solid #c9d3e3;border-radius:10px;font:inherit;font-size:15px;background:#fff;color:#1d2433}form input:focus,form textarea:focus{outline:2px solid #1d4ed8;outline-offset:1px;border-color:#1d4ed8}form textarea{resize:vertical;min-height:150px}form .btn{margin-top:16px}.hp{position:absolute;left:-9999px;top:-9999px;height:0;overflow:hidden}button.use{border:1px solid #c9d3e3;background:#fff;color:#0f2a4a;font:inherit;font-size:14px;font-weight:600;padding:7px 12px;border-radius:8px;cursor:pointer}button.use:hover{background:#0f2a4a;color:#fff;border-color:#0f2a4a}.warnbox{background:#fff8e6;border:1px solid #f1d58f;border-radius:10px;padding:10px 14px;font-size:14px;color:#6b4e00;margin-top:12px}`;
const page = (title, body, wide) => `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex"><title>${esc(title)}</title><style>${CSS}</style></head><body><main class="wrap${wide ? ' wide' : ''}"><header class="brand"><span class="logo">H</span><span>Harborline Software · Inbox assistant</span><span class="pill">Live demo</span></header>${body}<footer>Live demo built with n8n by Aqib ur Rehman · Harborline Software is a fictional company · test emails go to a demo inbox and drafted replies are never sent.</footer></main></body></html>`;
const notFoundPage = () => page('Not found', `<div class="card"><h1>We couldn't find that email</h1><p class="muted">The link may be old (results are kept for 7 days). Send a new test email below.</p><a class="btn" href="${BASE}">Try the inbox assistant</a></div>`);
// ---- end shared helpers ----

// Public page: write a test email (or pick a sample) and send it into the demo inbox
const SAMPLES = [
  { k: 'lead', name: 'Priya Nair', email: 'priya@nairaccounts.example.com', subject: 'Automating client onboarding emails – can you help?', body: "Hi,\n\nI run a 12-person accounting firm. Every new client gets the same 6 welcome emails, a questionnaire and a document checklist, and right now my assistant sends them by hand. We'd like this automated and connected to our CRM.\n\nCould we have a call this week? Budget is around $2k if the fit is right.\n\nThanks,\nPriya" },
  { k: 'support', name: 'Tom Becker', email: 'tom@beckerbakes.example.com', subject: 'Order #4521 STILL not delivered – third time asking', body: "This is the third email I've sent. Order #4521 was promised for Monday, it is now Thursday and nobody has replied. I have a customer event on Saturday and I need this resolved today or I want a refund.\n\nTom" },
  { k: 'billing', name: 'Emma Clarke', email: 'accounts@clarkeproperty.example.com', subject: 'Invoice INV-20431 – PO number missing', body: "Hello,\n\nWe received invoice INV-20431 for £550.80 but it does not show our PO number (PO-7781), so our system rejected it. Could you reissue it with the PO number? Payment run is on the 28th.\n\nKind regards,\nEmma Clarke\nAccounts payable, Clarke Property Group" },
  { k: 'meeting', name: 'Daniel Kim', email: 'daniel@kimlogistics.example.com', subject: 'Can we move Thursday\'s call to Friday?', body: "Hi,\n\nSomething came up on Thursday afternoon. Would Friday 10:00 or 14:00 UK time work for you instead? Same agenda.\n\nBest,\nDaniel" },
  { k: 'newsletter', name: 'Automation Weekly', email: 'news@automationweekly.example.com', subject: '📬 This week: 7 n8n templates, a webinar and 20% off', body: "Welcome to Automation Weekly!\n\n- 7 new workflow templates for e-commerce\n- Webinar: AI agents for support teams (Tuesday)\n- 20% off annual plans until Sunday\n\nYou are receiving this because you subscribed. Unsubscribe | Update preferences" },
  { k: 'suspicious', name: 'Account Security', email: 'security-alert@mail-verify-center.example.com', subject: 'URGENT: your account will be suspended in 24 hours', body: "Dear user,\n\nWe detected unusual sign-in activity. To avoid suspension, verify your identity within 24 hours by replying with your username and password or by clicking the secure link below.\n\nhttp://verify-account-now.example.com/login\n\nSecurity Team" },
];
const body = `<div class="card"><span class="st st-info">AI inbox assistant</span>
<h1>Every email sorted, labelled and answered in draft, before anyone opens the inbox</h1>
<p class="muted">Send a test email into the demo inbox. AI reads it, decides what it is and how urgent it is, applies Gmail labels, archives the noise and writes a reply as a Gmail draft for a human to check. Nothing is ever sent automatically.</p>
<form method="post" action="${BASE}" id="f">
<label>Sender name<input name="name" required maxlength="60" placeholder="Maria Lopez"></label>
<label>Subject<input name="subject" required maxlength="150" placeholder="Question about your automation services"></label>
<label>Message<textarea name="message" required rows="7" maxlength="2500" placeholder="Write anything a customer, lead, supplier or spammer might send…"></textarea></label>
<div class="hp" aria-hidden="true"><label>Website<input name="website" tabindex="-1" autocomplete="off"></label></div>
<input type="hidden" name="sample" id="sample" value="">
<button class="btn" type="submit">Send it to the inbox →</button>
<p class="small muted" style="margin-top:12px">Takes about 8 seconds. Please don't include real personal data; this is a public demo.</p></form>
<div class="warnbox">The test email is delivered to a demo Gmail inbox as if it came from the sender you name (at a made-up example.com address). Drafted replies stay in Gmail as drafts.</div></div>
<div class="card"><h2>Or pick a sample</h2><div class="samples">
${SAMPLES.map((s, i) => `<div class="sample"><h3>${esc(s.subject)}</h3><p>From ${esc(s.name)} · ${esc(CATS[s.k][0])}</p><button type="button" data-i="${i}" class="use">Use this</button></div>`).join('')}
</div></div>
<div class="card"><h2>What happens when you press the button</h2><ol class="small" style="margin:0;padding-left:20px">
<li>The email lands in the demo Gmail inbox.</li>
<li><b>Google Gemini</b> reads it and decides: lead, support, billing, meeting, newsletter, suspicious or other, plus priority and sentiment.</li>
<li>n8n applies <b>Gmail labels</b>, stars urgent items, archives newsletters and suspicious mail, and saves a <b>drafted reply</b> in the thread for the right emails.</li>
<li>A row is added to <b>Google Sheets</b> and the owner dashboard, so the team sees what came in and what still needs a human.</li></ol></div>
<script>
var S = ${JSON.stringify(SAMPLES.map((s) => ({ name: s.name, subject: s.subject, body: s.body })))};
document.querySelectorAll('button.use').forEach(function (b) { b.addEventListener('click', function () { var s = S[+b.dataset.i]; var f = document.getElementById('f'); f.name.value = s.name; f.subject.value = s.subject; f.message.value = s.body; document.getElementById('sample').value = String(+b.dataset.i + 1); f.scrollIntoView({ behavior: 'smooth', block: 'start' }); f.querySelector('button.btn').focus(); }); });
document.getElementById('f').addEventListener('submit', function () { var b = this.querySelector('button.btn'); b.textContent = 'Sending and reading…'; b.style.opacity = '.75'; });
</script>`;
return [{ json: { html: page('AI inbox assistant – Harborline Software', body) } }];

// Prepare the test email: validate, cap, build the MIME message that Gmail will file into the inbox
const SAMPLE_EMAILS = ['priya@nairaccounts.example.com', 'tom@beckerbakes.example.com', 'accounts@clarkeproperty.example.com', 'daniel@kimlogistics.example.com', 'news@automationweekly.example.com', 'security-alert@mail-verify-center.example.com'];
const f = $json.body || {};
const clean = (s, n) => String(s ?? '').replace(/[\r\n]+/g, ' ').replace(/\s+/g, ' ').trim().slice(0, n);
const name = clean(f.name, 60), subject = clean(f.subject, 150);
const message = String(f.message ?? '').replace(/\r\n/g, '\n').trim().slice(0, 2500);
const store = $getWorkflowStaticData('global');
const today = new Date().toISOString().slice(0, 10);
if (!store.day || store.day.date !== today) store.day = { date: today, count: 0 };
let problem = null;
if (f.website) problem = 'spam';
else if (!name || !subject || !message) problem = 'Please fill in the sender name, a subject and a message.';
else if (store.day.count >= 40) problem = 'This public demo has handled 40 test emails today, which is its daily limit. Please try again tomorrow.';
if (!problem) store.day.count += 1;
const chars = 'abcdefghijkmnpqrstuvwxyz23456789';
const token = Array.from({ length: 24 }, () => chars[Math.floor(Math.random() * chars.length)]).join('');
const sampleNo = parseInt(f.sample, 10);
const local = name.toLowerCase().replace(/[^a-z0-9]+/g, '.').replace(/^\.|\.$/g, '') || 'visitor';
const fromEmail = SAMPLE_EMAILS[sampleNo - 1] || (local + '@example.com');
const b64 = (s) => Buffer.from(String(s), 'utf8').toString('base64');
const enc = (s) => '=?UTF-8?B?' + b64(s) + '?=';
const mime = [`From: ${enc(name)} <${fromEmail}>`, 'To: Harborline Software <your-inbox@gmail.com>', 'Subject: ' + enc(subject), 'Date: ' + new Date().toUTCString(), `Message-ID: <${token}@harborline-demo.example>`, 'X-Harborline-Demo: ' + token, 'MIME-Version: 1.0', 'Content-Type: text/plain; charset=UTF-8', 'Content-Transfer-Encoding: base64', '', b64(message).replace(/.{1,76}/g, (m) => m + '\r\n')].join('\r\n');
const raw = b64(mime).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
return [{ json: { valid: !problem, problem, token, name, fromEmail, subject, message, insertBody: problem ? null : { raw, labelIds: ['INBOX', 'UNREAD'] } } }];

