.mail{border:1px solid #e3e8ef;border-radius:12px;padding:14px 16px;background:#fff}.mail .hd{font-size:13px;color:#5b6576;margin-bottom:8px}.mail .hd b{color:#1d2433}
form label{display:block;font-weight:600;font-size:14px;color:#344054;margin:14px 0 6px}form input:not([type=hidden]),form textarea{display:block;width:100%;padding:11px 12px;border:1px solid #c9d3e3;border-radius:10px;font:inherit;font-size:15px;background:#fff;color:#1d2433}form input:focus,form textarea:focus{outline:2px solid #1d4ed8;outline-offset:1px;border-color:#1d4ed8}form textarea{resize:vertical;min-height:150px}form .btn{margin-top:16px}.hp{position:absolute;left:-9999px;top:-9999px;height:0;overflow:hidden}button.use{border:1px solid #c9d3e3;background:#fff;color:#0f2a4a;font:inherit;font-size:14px;font-weight:600;padding:7px 12px;border-radius:8px;cursor:pointer}button.use:hover{background:#0f2a4a;color:#fff;border-color:#0f2a4a}.warnbox{background:#fff8e6;border:1px solid #f1d58f;border-radius:10px;padding:10px 14px;font-size:14px;color:#6b4e00;margin-top:12px}`;
const page = (title, body, wide) => `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex"><title>${esc(title)}</title><style>${CSS}</style></head><body><main class="wrap${wide ? ' wide' : ''}"><header class="brand"><span class="logo">H</span><span>Harborline Software · Inbox assistant</span><span class="pill">Live demo</span></header>${body}<footer>Live demo built with n8n by Aqib ur Rehman · Harborline Software is a fictional company · test emails go to a demo inbox and drafted replies are never sent.</footer></main></body></html>`;
const notFoundPage = () => page('Not found', `<div class="card"><h1>We couldn't find that email</h1><p class="muted">The link may be old (results are kept for 7 days). Send a new test email below.</p><a class="btn" href="${BASE}">Try the inbox assistant</a></div>`);
// ---- end shared helpers ----

// Owner dashboard: everything triaged in the last 7 days
const msgs = ($getWorkflowStaticData('global').msgs || []).filter((r) => r.status === 'triaged');
const n = (f) => msgs.filter(f).length;
const rows = msgs.slice(0, 150).map((r) => { const cat = CATS[r.category] || CATS.other; return `<tr><td>${new Date(r.triagedAt || r.createdAt).toLocaleString('en-GB', { timeZone: 'Europe/London', day: '2-digit', month: 'short', hour: '2-digit', minute: '2-digit' })}<br><span class="muted small">${esc(r.source)}</span></td><td><b>${esc(r.fromName)}</b><br><span class="muted small">${esc(r.fromEmail)}</span></td><td>${esc(r.subject)}<br><span class="muted small">${esc(r.summary)}</span></td><td><span class="st ${cat[1]}">${esc(cat[0])}</span><br><span class="st ${PRIO[r.priority]}" style="margin-top:4px">${esc(r.priority)}</span></td><td class="small">${esc(r.nextStep)}<br><span class="muted">${r.needsReply ? (r.draftOk ? 'Draft ready' : 'Draft failed') : r.archived ? 'Archived' : 'No reply needed'}</span></td><td><a href="https://mail.google.com/mail/#all/${esc(r.threadId)}" target="_blank">Gmail</a><br><a href="${BASE}/result?t=${r.token}" target="_blank">detail</a></td></tr>`; }).join('');
const body = `<h1>Inbox assistant – owner view</h1><p class="muted">Last 7 days · ${new Date().toLocaleString('en-GB', { timeZone: 'Europe/London', dateStyle: 'medium', timeStyle: 'short' })} UK</p>
<div class="kpis"><div class="kpi"><b>${msgs.length}</b>Emails triaged</div><div class="kpi"><b>${n((r) => r.priority === 'high' && !r.archived)}</b>Urgent</div><div class="kpi"><b>${n((r) => r.category === 'lead')}</b>Leads</div><div class="kpi"><b>${n((r) => r.needsReply && r.draftOk)}</b>Drafts ready</div><div class="kpi"><b>${n((r) => r.archived)}</b>Archived (noise)</div></div>
<div class="card" style="overflow-x:auto"><table><tr><th>When</th><th>From</th><th>Email</th><th>Category</th><th>Next step</th><th>Open</th></tr>${rows || '<tr><td colspan="6">Nothing yet.</td></tr>'}</table></div>
<p class="small muted">Full log: <a href="https://docs.google.com/spreadsheets/d/YOUR_SHEET_ID/edit" target="_blank">Google Sheets (Inbox triage tab)</a></p>`;
return [{ json: { html: page('Inbox assistant – owner view', body, true) } }];
